-- Disposable database only, composed inside an outer rollback transaction.
do $test$
declare reviewer uuid:='10000000-0000-4000-8000-000000000007';
 b uuid:='20000000-0000-4000-8000-000000000001';other_b uuid:='20000000-0000-4000-8000-000000000019';c uuid;other_c uuid;data jsonb;count_before bigint;test_request uuid:=gen_random_uuid();
begin
 if current_database()<>'vetit_disposable_corrections_20261018_1302' or session_user<>'vetit_test_admin' or inet_server_addr()<>'127.0.0.1'::inet or inet_server_port()<>55432 then raise exception 'Wrong disposable target.';end if;
 insert into public.businesses(id,display_name,business_type,public_email) values(other_b,'Synthetic scoped acceptance','company','synthetic-scoped@example.invalid');
 insert into vetit_moderation.reviewers(profile_id,enabled) values(reviewer,true) on conflict(profile_id) do nothing;
 update auth.users set raw_app_meta_data=coalesce(raw_app_meta_data,'{}')||'{"vetit_reviewer":true}'::jsonb where id=reviewer;
 perform set_config('request.jwt.claim.sub',reviewer::text,true);perform set_config('request.jwt.claims','{"app_metadata":{"vetit_reviewer":true}}',true);
 if vetit_moderation.has_scope(b,'read') then raise exception 'Unscoped reviewer accepted.';end if;
 insert into vetit_moderation.reviewer_scopes(profile_id,business_id,enabled,expires_at) values(reviewer,b,true,clock_timestamp()+interval '10 minutes');
 if not vetit_moderation.has_scope(b,'read') or vetit_moderation.has_scope(other_b,'read') or vetit_moderation.has_scope(b,'review') or vetit_moderation.has_scope(b,'publish') then raise exception 'Scope isolation failed.';end if;
 begin perform vetit_moderation.require_scope(b,'review');raise exception 'Read-only review permitted.';exception when insufficient_privilege then null;end;
 insert into vetit_moderation.cases(subject_kind,subject_id,business_id,revision) values('seller',b,b,repeat('a',64)) returning id into c;
 insert into vetit_moderation.cases(subject_kind,subject_id,business_id,revision) values('seller',other_b,other_b,repeat('b',64)) returning id into other_c;
 set local role authenticated;
 data:=public.moderation_queue();if jsonb_array_length(data->'items')<>1 or data->'items'->0->>'id'<>c::text then raise exception 'Queue crossed business boundary.';end if;
 perform public.moderation_status('seller',b);
 begin perform public.moderation_status('seller',other_b);raise exception 'Cross-business status accepted.';exception when insufficient_privilege then null;end;
 begin perform public.moderation_decide(c,1,'reject',gen_random_uuid(),array['SYNTHETIC']);raise exception 'Read-only decision accepted.';exception when insufficient_privilege then null;end;
 begin perform public.review_seller_business(other_b,'suspended');raise exception 'Legacy scope bypass.';exception when insufficient_privilege then null;end;
 reset role;
 raise notice 'PASS scoped queue, status/history, read-only decisions, legacy bypass denial';
 update vetit_moderation.reviewer_scopes set can_review=true where profile_id=reviewer and business_id=b;
 if not vetit_moderation.has_scope(b,'review') or vetit_moderation.has_scope(b,'publish') then raise exception 'Publish separation failed.';end if;
 update vetit_moderation.cases set revision=vetit_moderation.fingerprint('seller',b) where id=c;
 set local role authenticated;
 begin perform public.moderation_decide(c,1,'approve',gen_random_uuid());raise exception 'Review-only publication permitted.';exception when insufficient_privilege then null;end;
 data:=public.moderation_decide(c,1,'reject',test_request,array['SYNTHETIC_REVIEW']);
 if data->>'state'<>'rejected' then raise exception 'Scoped rejection failed.';end if;
 if public.moderation_decide(c,1,'reject',test_request,array['SYNTHETIC_REVIEW'])<>data then raise exception 'Scoped replay differs.';end if;
 reset role;
 if (select count(*) from vetit_moderation.events where request_id=test_request)=0 then raise exception 'Decision audit missing.';end if;
 update vetit_moderation.reviewer_scopes set enabled=false where profile_id=reviewer and business_id=b;
 set local role authenticated;
 begin perform public.moderation_decide(c,1,'reject',test_request,array['SYNTHETIC_REVIEW']);raise exception 'Revoked replay permitted.';exception when insufficient_privilege then null;end;
 reset role;
 update vetit_moderation.reviewer_scopes set enabled=true where profile_id=reviewer and business_id=b;
 raise notice 'PASS scoped audited rejection, idempotency, publish denial and revoked replay denial';
 update vetit_moderation.reviewer_scopes set expires_at=clock_timestamp()-interval '1 hour' where profile_id=reviewer and business_id=b;
 if vetit_moderation.has_scope(b,'read') then raise exception 'Expired scope accepted.';end if;
 update vetit_moderation.reviewer_scopes set expires_at=clock_timestamp()+interval '10 minutes' where profile_id=reviewer and business_id=b;
 update auth.users set raw_app_meta_data='{}' where id=reviewer;
 if vetit_moderation.has_scope(b,'read') then raise exception 'Stale JWT survived trusted metadata revocation.';end if;
 if not exists(select 1 from vetit_moderation.scope_events where next_grant->>'business_id'=b::text) then raise exception 'Grant audit absent.';end if;
 begin update vetit_moderation.scope_events set operation='tampered';raise exception 'Audit mutable.';exception when insufficient_privilege then null;end;
 if has_table_privilege('authenticated','vetit_moderation.reviewer_scopes','INSERT') or has_table_privilege('service_role','vetit_moderation.reviewer_scopes','UPDATE') then raise exception 'Client grant access.';end if;
 raise notice 'PASS action separation, expiry, current metadata revocation, immutable grant audit and ACL';
end;$test$;
